function validate([nums, a, b, c]) {
  if (nums.length < 1 || nums.length > 200) return 'nums needs 1 to 200 values.';
  if (nums.some(v => v < -100 || v > 100)) return 'Each value in nums is between -100 and 100.';
  for (let i = 1; i < nums.length; i++) if (nums[i - 1] > nums[i]) return 'nums must be sorted in non-decreasing order.';
  if ([a, b, c].some(v => v < -100 || v > 100)) return 'a, b and c are between -100 and 100.';
  return null;
}

