function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const coefficient = () => (rand() < 0.2 ? 0 : int(-100, 100));
  const n = size === 'large' ? 200 : int(1, 10);
  const span = size === 'large' || rand() < 0.5 ? 100 : 6;
  const nums = Array.from({ length: n }, () => int(-span, span)).sort((p, q) => p - q);
  return [nums, coefficient(), coefficient(), coefficient()];
}
